import re,glob,json,collections,sys
tag=re.compile(r'<([a-zA-Z][\w-]*)((?:\s+(?:"[^"]*"|\'[^\']*\'|[^>"\'])*)?)\s*/?>|<!--.*?-->',re.S)
attr=re.compile(r'([^\s=/"\'<>]+)(?:\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+)))?')
def tpls(f):
    s=open(f).read()
    if f.endswith('.html'): yield s,False
    else:
        for m in re.finditer(r'template\s*:\s*`(.*?)`',s,re.S): yield m.group(1),True
R=dict(pill=0,inl=0,dis=0,warn=0,nonlit=0,novar=0)
names=collections.Counter()
for f in glob.glob('src/**/*',recursive=True):
    if not f.endswith(('.ts','.html')): continue
    for t,inl in tpls(f):
        t=re.sub(r'<!--.*?-->','',t,flags=re.S)
        for m in tag.finditer(t):
            if not m.group(1): continue
            n=m.group(1); attrs=[(a.group(1),next((g for g in a.groups()[1:] if g is not None),None)) for a in attr.finditer(m.group(2) or '')]
            if n=='app-pill':
                R['pill']+=1; R['inl']+=inl
                for a,v in attrs: names[a]+=1
                vs=[(a,v) for a,v in attrs if re.sub(r'^(\[|bind-|\[attr\.)|\]$','',a)=='variant' or a in('[attr.variant]',)]
                if not vs: R['novar']+=1
                else:
                    a,v=vs[0]
                    if a=='variant':
                        if v=='warning': R['warn']+=1
                    else:
                        if re.search(r'''(["'`])warning\1''',v or ''): R['warn']+=1
                        if not re.search(r'''["'`]''',v or ''): R['nonlit']+=1; print(f,a,v,file=sys.stderr)
            else:
                if any(re.sub(r'^\[|\]$','',a).lower().replace('attr.','')=='disabletooltip' or a.lower().endswith('disabletooltip') for a,v in attrs): R['dis']+=1
print(R,names)
